pragma solidity 0.8.27;

contract G {
    mapping(bytes32 => bool) public good;
    constructor() {
        good[keccak256(abi.encode(bytes4(0x11223344)))] = true;
        good[keccak256(abi.encode(uint256(0x55667788)))] = true;
        good[keccak256(abi.encode(bytes2(0x1122)))] = true;
        good[keccak256(abi.encode(bytes3(0x445566)))] = true;
        good[keccak256(abi.encode(int8(-1)))] = true;
        good[keccak256(abi.encode(uint256(0xfffe)))] = true;
        good[keccak256(abi.encode(address(0xBEEF)))] = true;
        good[keccak256(abi.encode(true))] = true;
        good[keccak256(abi.encode(uint8(9)))] = true;
        good[keccak256(abi.encode(uint64(1 << 40)))] = true;
        good[keccak256(abi.encode(uint256(1 << 200)))] = true;
        good[keccak256(abi.encode(uint256(7), bytes4(0x11223344)))] = true;
        good[keccak256(abi.encodePacked(bytes4(0x11223344)))] = true;
        good[keccak256(abi.encodeWithSelector(bytes4(0xaabbccdd), bytes4(0x11223344)))] = true;
        good[keccak256(abi.encode("hi"))] = true;
    }
    function ok(bytes memory d) external view returns (bool) { return good[keccak256(d)]; }
}
contract C {
    G public g;
    uint256 public x;
    bytes4 public tag = 0x11223344;
    bytes4 public other = 0x55667788;
    bytes2 public b2 = 0x1122;
    int8 public neg = -1;
    int16 public neg16 = -2;
    address public who = address(0xBEEF);
    bool public flag = true;
    uint8 public small = 9;
    uint64 public mid = uint64(1 << 40);
    uint256 public big = 1 << 200;
    string public s = "hi";
    constructor(G z) { g = z; }
    function _k(bytes4 t) internal view returns (bool) { return g.ok(abi.encode(t)); }
    function storedBytes() external { require(g.ok(abi.encode(tag))); x = 1; }
    // Its word as an integer would be in G; as a bytes4 it isn't: nobody passes.
    function storedBytesNot() external { require(g.ok(abi.encode(other))); x = 1; }
    function exprBytes() external { require(g.ok(abi.encode(b2 ^ bytes2(0)))); x = 1; }
    function literalBytes() external { require(g.ok(abi.encode(bytes3(0x445566)))); x = 1; }
    function argBytes() external { require(_k(tag)); x = 1; }
    function signedSmall() external { require(g.ok(abi.encode(neg))); x = 1; }
    // Sign-extended, -2 is not 0xfffe: nobody passes.
    function signedSmallNot() external { require(g.ok(abi.encode(neg16))); x = 1; }
    function addr() external { require(g.ok(abi.encode(who))); x = 1; }
    function boolean() external { require(g.ok(abi.encode(flag))); x = 1; }
    function uint8w() external { require(g.ok(abi.encode(small))); x = 1; }
    function uint64w() external { require(g.ok(abi.encode(mid))); x = 1; }
    function uint256w() external { require(g.ok(abi.encode(big))); x = 1; }
    function pair() external { require(g.ok(abi.encode(uint256(7), tag))); x = 1; }
    function packed() external { require(g.ok(abi.encodePacked(tag))); x = 1; }
    function selector() external { require(g.ok(abi.encodeWithSelector(bytes4(0xaabbccdd), tag))); x = 1; }
    function dynamic() external { require(g.ok(abi.encode(s))); x = 1; }
}

pragma solidity 0.8.27;

interface I { function k(bytes4) external; }
type Sel is bytes4;

contract Good {
    mapping(bytes32 => bool) public good;
    function set(bytes32 h) external { good[h] = true; }
    function ok(bytes memory d) external view returns (bool) { return good[keccak256(d)]; }
}

// Review 5's encodings (``q3``/``q3b``): items of every kind, each handed to ``Good`` keyed on its hash.
contract Items {
    struct S { uint128 a; uint128 b; }
    Good public g; uint256 public x;
    S public s;
    uint256[2] public arr;
    bytes public bs = hex"11223344";
    bytes4 public b4 = 0x11223344;
    enum E { A, B, C2 }
    E public e = E.C2;
    function() external fp;
    int8 public n8 = -1; int128 public n128 = -2; int256 public n256 = -3;
    uint public u = 7;
    string public sigStr = "f(uint256)";
    address payable public pay = payable(address(0xBEEF));
    Sel public sel = Sel.wrap(0x11223344);
    function target() external {}
    constructor(Good z, bool seed) {
        g = z; s = S(1, 2); arr = [uint256(3), 4]; fp = this.target;
        uint256 rs; uint256 rb; uint256 rf;
        assembly { rs := sload(s.slot) rb := sload(bs.slot) rf := sload(fp.slot) }
        if (seed) {  // the true encodings: functions named f* pass
            z.set(keccak256(abi.encode(s)));
            z.set(keccak256(abi.encode(arr)));
            z.set(keccak256(abi.encode(bs)));
            z.set(keccak256(abi.encode(e)));
            z.set(keccak256(abi.encode(z)));
            z.set(keccak256(abi.encode(fp)));
            z.set(keccak256(abi.encode(n8)));
            z.set(keccak256(abi.encode(n128)));
            z.set(keccak256(abi.encode(n256)));
            z.set(keccak256(abi.encode(u)));
            z.set(keccak256(abi.encodeWithSignature(sigStr, uint256(1))));
            z.set(keccak256(abi.encode(bytes4(keccak256("fMsgSig()")))));
            z.set(keccak256(abi.encodePacked(bytes4(keccak256("fPackedSig()")), uint8(1))));
            z.set(keccak256(abi.encode(pay)));
            z.set(keccak256(abi.encode(sel)));
            z.set(keccak256(abi.encodeCall(I.k, (b4))));
        }
        // Encodings a lowering laying an item out wrongly would produce: w* never pass now.
        z.set(keccak256(abi.encode(rs)));
        z.set(keccak256(abi.encode(uint256(1))));
        z.set(keccak256(abi.encode(uint256(3))));
        z.set(keccak256(abi.encode(rb)));
        z.set(keccak256(abi.encode(uint256(0x11223344))));
        z.set(keccak256(abi.encode(rf)));
        z.set(keccak256(abi.encode(uint256(uint8(int8(-1))))));
        z.set(keccak256(abi.encode(uint256(uint128(int128(-2))))));
        z.set(keccak256(abi.encode(uint256(uint32(bytes4(keccak256("wMsgSig()")))))));
        z.set(keccak256(abi.encodePacked(uint256(uint32(bytes4(keccak256("wPackedSig()")))), uint8(1))));
        z.set(keccak256(abi.encode(uint256(uint32(bytes4(keccak256("wSlice()")))))));
        z.set(keccak256(abi.encode(bytes4(keccak256("wSlice()")))));
    }
    function fStruct() external { require(g.ok(abi.encode(s))); x = 1; }
    function fArr() external { require(g.ok(abi.encode(arr))); x = 1; }
    function fBytes() external { require(g.ok(abi.encode(bs))); x = 1; }
    function fEnum() external { require(g.ok(abi.encode(e))); x = 1; }
    function fContract() external { require(g.ok(abi.encode(g))); x = 1; }
    function fFn() external { require(g.ok(abi.encode(fp))); x = 1; }
    function fN8() external { require(g.ok(abi.encode(n8))); x = 1; }
    function fN128() external { require(g.ok(abi.encode(n128))); x = 1; }
    function fN256() external { require(g.ok(abi.encode(n256))); x = 1; }
    function fUint() external { require(g.ok(abi.encode(u))); x = 1; }
    function fSigStr() external { require(g.ok(abi.encodeWithSignature(sigStr, uint256(1)))); x = 1; }
    function fMsgSig() external { require(g.ok(abi.encode(msg.sig))); x = 1; }
    function fPackedSig() external { require(g.ok(abi.encodePacked(msg.sig, uint8(1)))); x = 1; }
    function fPay() external { require(g.ok(abi.encode(pay))); x = 1; }
    function fUdvt() external { require(g.ok(abi.encode(sel))); x = 1; }
    function fCall() external { require(g.ok(abi.encodeCall(I.k, (b4)))); x = 1; }
    function wMsgSig() external { require(g.ok(abi.encode(msg.sig))); x = 1; }
    function wPackedSig() external { require(g.ok(abi.encodePacked(uint256(uint32(msg.sig)), uint8(2)))); x = 1; }
    function wSlice() external { require(g.ok(abi.encode(msg.data[0:4]))); x = 1; }
    function wSliceB4() external { require(g.ok(abi.encode(bytes4(msg.data[0:4])))); x = 1; }
    function wN8neg(int8 v) external { require(v < 0); require(g.ok(abi.encode(v))); x = 1; }
}

contract Seeded is Items { constructor(Good z) Items(z, true) {} }
contract Unseeded is Items { constructor(Good z) Items(z, false) {} }

pragma solidity 0.8.27;

contract Token {
    mapping(address => uint256) balanceOf;
    mapping(address => mapping(address => uint256)) allowance;

    constructor() { balanceOf[msg.sender] = 1e24; }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount);
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount && allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

contract Vault {
    Token token;

    constructor(Token t) { token = t; }

    function deposit(uint256 amount) external {
        require(amount > 0);
        token.transferFrom(msg.sender, address(this), amount);
    }

    // A fixed fee: a stranger without tokens fails until it gets some (from any holder) and approves the vault.
    function payFee() external {
        token.transferFrom(msg.sender, address(this), 100);
    }

    mapping(address => uint256) nonces;

    // Aave's ``depositWithSig``: anyone relays a holder's signed deposit, the holder's tokens pulled in.
    function depositSigned(
        address owner, uint256 amount, uint256 nonce, uint256 deadline, uint8 v, bytes32 r, bytes32 s
    )
        external
    {
        require(block.timestamp <= deadline && amount > 0);
        require(ecrecover(keccak256(abi.encode(owner, amount, nonce, deadline)), v, r, s) == owner);
        require(nonce == nonces[owner]);
        nonces[owner] = nonce + 1;
        token.transferFrom(owner, address(this), amount);
    }

    // Paying ether out is an action too.
    function refund() external {
        payable(msg.sender).transfer(address(this).balance);
    }

    // A checked action: the call is both a condition and a revert point.
    function payOut(uint256 amount) external {
        require(token.transfer(msg.sender, amount));
    }
}

// Paxos' SupplyControl shape: a state-changing check of who may mint, handed the minter.
contract Supply {
    address admin;
    mapping(address => bool) controllers;
    mapping(address => uint256) minted;

    constructor() { admin = msg.sender; }

    function addController(address who) external {
        require(msg.sender == admin);
        controllers[who] = true;
    }

    function canMint(address sender, uint256 amount) external {
        require(controllers[sender]);
        minted[sender] += amount;
    }
}

contract Minter {
    Supply supply;
    uint256 total;

    constructor(Supply s) { supply = s; }

    function mint(uint256 amount) external {
        supply.canMint(msg.sender, amount);
        total += amount;
    }
}

pragma solidity 0.8.27;

contract C {
    address owner;
    bool initialized;
    mapping(address => uint256) balances;
    mapping(address => bool) members;
    mapping(address => mapping(address => bool)) operators;
    mapping(address => mapping(address => bool)) approved;

    constructor() { owner = msg.sender; }

    function deposit(uint256 amount) external {
        require(amount > 0);
        balances[msg.sender] += amount;
    }

    function setOperator(address operator, bool on) external {
        operators[msg.sender][operator] = on;
    }

    function approve(address spender) external {
        approved[msg.sender][spender] = true;
    }

    function grant(address who) external {
        require(msg.sender == owner);
        members[who] = true;
    }

    // Already run: the membership it hands its caller is no one's to take now.
    function initialize() external {
        require(!initialized);
        initialized = true;
        members[msg.sender] = true;
    }

    // OpenZeppelin's ``_revokeRole`` shape: written only when held.
    function renounce() external {
        if (members[msg.sender]) {
            members[msg.sender] = false;
        }
    }

    function withdraw(uint256 amount) external {
        require(amount > 0 && balances[msg.sender] >= amount);
        balances[msg.sender] -= amount;
    }

    function withdrawFor(address account, uint256 amount) external {
        require(account == msg.sender || operators[account][msg.sender]);
        require(amount > 0 && balances[account] >= amount);
        balances[account] -= amount;
    }

    function membersOnly() external view {
        require(members[msg.sender]);
    }

    // Approval only someone else can give: a caller can't stand in for ``from``.
    function pull(address from) external view {
        require(from != msg.sender && approved[from][msg.sender]);
    }
}

pragma solidity 0.8.27;

contract Tickets {
    struct Ticket { address owner; bool used; }
    mapping(uint256 => Ticket) tickets;
    mapping(uint256 => address) approvals;
    uint256 last;

    // Open: whoever asks gets a ticket (Lido's withdrawal requests).
    function request(address owner) external returns (uint256 id) {
        id = ++last;
        tickets[id] = Ticket(owner == address(0) ? msg.sender : owner, false);
    }

    function approve(address to, uint256 id) external {
        require(tickets[id].owner == msg.sender && to != msg.sender);
        approvals[id] = to;
    }
}

contract Badges {
    address admin;
    address owner;

    constructor(address o) { admin = msg.sender; owner = o; }

    // Anyone may become owner of nothing in particular: still the one owner, taken from whoever held it.
    function claim() external {
        require(owner == address(0));
        owner = msg.sender;
    }

    function ownerOnly() external view {
        require(owner == msg.sender);
    }
    mapping(uint256 => address) owners;
    mapping(uint256 => address) approvals;

    // Only the admin mints (ENS's controllers, a staking manager).
    function mint(uint256 id, address to) external {
        require(msg.sender == admin);
        owners[id] = to;
    }

    function approve(address to, uint256 id) external {
        require(owners[id] == msg.sender);
        approvals[id] = to;
    }
}

// The same badges with the owner never set: whoever claims first is it.
contract Unclaimed is Badges {
    constructor() Badges(address(0)) {}
}

pragma solidity 0.8.27;

// A role whose holders no event lists, and a start time still to come.
contract Gates {
    uint256 quorum;
    uint256 start;
    mapping(address => bool) managers;
    uint8 initialized;
    uint256 deadline;

    constructor(uint256 s, uint256 d) {
        quorum = 5; start = s; deadline = d; initialized = 1;
        managers[msg.sender] = true;
    }

    function addManager(address who) external {
        require(managers[msg.sender]);
        managers[who] = true;
    }

    // HashConsensus's ``disableConsensus``: anyone once it is already disabled, a manager otherwise.
    function disable() external {
        if (quorum != type(uint256).max) {
            require(managers[msg.sender]);
            quorum = type(uint256).max;
        }
    }

    function report() external view {
        require(block.timestamp >= start);
        require(managers[msg.sender]);
    }

    function presale() external view {
        require(block.timestamp < deadline);
    }

    // OpenZeppelin's initializer: never run, or run once and still being constructed.
    function initialize() external {
        require(initialized == 0 || (initialized == 1 && address(this).code.length == 0));
        initialized = 1;
    }
}

// OpenZeppelin 5's layout: roles in an ERC-7201 struct, granted without an event.
contract Spaced {
    struct Roles {
        mapping(address => bool) managers;
    }

    uint256 quorum;

    bytes32 private constant SLOT = 0x02dd7bc7dec4dceedda775e58dd541e08a116c6c53815c0bd028192f7b626800;

    constructor() { quorum = 5; _roles().managers[msg.sender] = true; }

    function _roles() private pure returns (Roles storage $) {
        assembly {
            $.slot := SLOT
        }
    }

    function add(address who) external {
        require(_roles().managers[msg.sender]);
        _roles().managers[who] = true;
    }

    function act() external view {
        require(_roles().managers[msg.sender]);
    }

    // Anyone once already disabled, a manager otherwise.
    function disable() external {
        if (quorum != type(uint256).max) {
            require(_roles().managers[msg.sender]);
            quorum = type(uint256).max;
        }
    }
}

// Lido's ``burnShares``: one address may burn, and only shares it holds; the holders are every staker.
contract Burner {
    address burner;
    mapping(address => uint256) shares;
    uint256 total;
    event TransferShares(address indexed from, address indexed to, uint256 amount);

    constructor() { burner = msg.sender; }

    function stake() external payable {
        shares[msg.sender] += msg.value;
        emit TransferShares(address(0), msg.sender, msg.value);
    }

    function burn(uint256 amount) external {
        require(msg.sender == burner);
        require(shares[msg.sender] >= amount);
        shares[msg.sender] -= amount;
        total -= amount;
        emit TransferShares(msg.sender, address(0), amount);
    }
}

interface ICounter {
    function count() external view returns (uint256);
}

contract Counter {
    function count() external pure returns (uint256) { return 3; }
}

// Lido CSM's ``depositETH``: nobody is singled out, and an id must be below another contract's count.
contract Counted {
    ICounter counter;

    constructor(ICounter c) { counter = c; }

    function act(uint256 id) external view {
        require(id < counter.count());
    }
}

// A switch only managers turn off, which anyone may "turn off" again once it is off, and a deposit a manager pauses.
contract Switch {
    uint256 quorum;
    bool paused;
    mapping(address => bool) managers;
    mapping(address => uint256) balances;
    event ManagerAdded(address indexed who);

    constructor() { quorum = 5; paused = true; managers[msg.sender] = true; emit ManagerAdded(msg.sender); }

    function addManager(address who) external {
        require(managers[msg.sender]);
        managers[who] = true;
        emit ManagerAdded(who);
    }

    function disable() external {
        if (quorum != type(uint256).max) {
            require(managers[msg.sender]);
        }
        quorum = type(uint256).max;
    }

    function pause(bool on) external {
        require(managers[msg.sender]);
        paused = on;
    }

    function deposit() external payable {
        require(!paused);
        balances[msg.sender] += msg.value;
    }
}

// EtherFi's ``finalizeWithdrawalsWhenStale``: anyone once a block window passes, unless paused or blocked.
contract Window {
    uint256 start;
    bool paused;
    mapping(address => bool) blocked;
    event Blocked(address indexed who);

    constructor(uint256 s) { start = s; }

    function block_(address who) external {
        require(!blocked[msg.sender]);
        blocked[who] = true;
        emit Blocked(who);
    }

    function go() external view {
        require(block.number >= start);
        require(!paused);
        require(!blocked[msg.sender]);
    }
}

// WeETH's ``unwrap``: only a holder may withdraw, and anyone becomes one by depositing, unless deposits are closed.
contract Bank {
    bool closed;
    mapping(address => uint256) balances;
    mapping(address => uint256) paid;

    function deposit() external payable {
        require(!closed);
        balances[msg.sender] += msg.value;
    }

    function withdraw(uint256 amount) external {
        require(amount > 0 && balances[msg.sender] >= amount && paid[msg.sender] == 0);
        paid[msg.sender] = amount;
    }
}

// OpenZeppelin's AccessControl, trimmed: each role's holders and the role that administers it.
contract Roles {
    struct RoleData {
        mapping(address => bool) members;
        bytes32 adminRole;
    }
    mapping(bytes32 => RoleData) private _roles;
    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;
    bytes32 public constant MANAGER = keccak256("MANAGER");
    bytes32 public constant OPERATOR = keccak256("OPERATOR");

    event RoleAdminChanged(bytes32 indexed role, bytes32 indexed previousAdminRole, bytes32 indexed newAdminRole);
    event RoleGranted(bytes32 indexed role, address indexed account, address indexed sender);
    event RoleRevoked(bytes32 indexed role, address indexed account, address indexed sender);

    function initialize(address admin) external {
        require(!_roles[DEFAULT_ADMIN_ROLE].members[admin]);
        _grant(DEFAULT_ADMIN_ROLE, admin);
        _setRoleAdmin(OPERATOR, MANAGER);
    }

    function hasRole(bytes32 role, address account) public view returns (bool) {
        return _roles[role].members[account];
    }

    function getRoleAdmin(bytes32 role) public view returns (bytes32) {
        return _roles[role].adminRole;
    }

    function grantRole(bytes32 role, address account) external {
        require(hasRole(getRoleAdmin(role), msg.sender));
        _grant(role, account);
    }

    function revokeRole(bytes32 role, address account) external {
        require(hasRole(getRoleAdmin(role), msg.sender));
        _roles[role].members[account] = false;
        emit RoleRevoked(role, account, msg.sender);
    }

    function _grant(bytes32 role, address account) internal {
        _roles[role].members[account] = true;
        emit RoleGranted(role, account, msg.sender);
    }

    function _setRoleAdmin(bytes32 role, bytes32 adminRole) internal {
        bytes32 previous = _roles[role].adminRole;
        _roles[role].adminRole = adminRole;
        emit RoleAdminChanged(role, previous, adminRole);
    }
}

// USDT's ``approve``: an allowance must be zeroed before it is changed.
contract Tether {
    mapping(address => mapping(address => uint256)) allowed;
    event Approval(address indexed owner, address indexed spender, uint256 value);

    function approve(address spender, uint256 value) external {
        require(msg.data.length >= 68);  // ``onlyPayloadSize(2 * 32)``
        require(value == 0 || allowed[msg.sender][spender] == 0);
        allowed[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
    }
}

// A transient reentrancy lock (OpenZeppelin's ReentrancyGuardTransient) and OpenZeppelin's ``mulDiv`` remainder.
contract Locked {
    address owner;

    constructor() { owner = msg.sender; }

    modifier nonReentrant() {
        assembly {
            if tload(0x1234) { revert(0, 0) }
            tstore(0x1234, 1)
        }
        _;
        assembly {
            tstore(0x1234, 0)
        }
    }

    function sweep() external nonReentrant {
        require(msg.sender == owner);
    }

    function poke() external nonReentrant {}

    function split(uint256 amount) external view {
        require(amount > 0 && mulmod(amount, 3, 7) == 3);
    }
}

interface IRegistry {
    function allowed(address who) external view returns (bool);
}

contract Registry {
    address owner;
    constructor() { owner = msg.sender; }
    function allowed(address who) external view returns (bool) { return who == owner; }
}

// The owner's check, beside a registry's check of the caller the node can't answer: only running the call settles it.
contract Gassy {
    address owner;
    IRegistry registry;

    constructor(IRegistry r) { owner = msg.sender; registry = r; }

    function act(uint256 amount) external view {
        require(msg.sender == owner && amount > 0);
        require(registry.allowed(msg.sender));
    }
}

// LayerZero's ``nilify`` / ``clear``: anyone can mark its own entry nil, but only a payload's hash clears it.
contract Inbox {
    address admin;
    mapping(address => bytes32) stored;

    constructor() { admin = msg.sender; }

    function nilify() external {
        stored[msg.sender] = bytes32(type(uint256).max);
    }

    function verify(address who, bytes32 hash) external {
        require(msg.sender == admin);
        stored[who] = hash;
    }

    function clear(bytes calldata message) external {
        require(stored[msg.sender] == keccak256(message));
        stored[msg.sender] = 0;
    }
}

// Lido's withdrawal queue: a request is its owner's to claim, and anyone files one, unless requests are closed.
contract Queue {
    bool closed;
    uint256 next;
    mapping(uint256 => address) owners;
    mapping(uint256 => bool) claimed;

    function request() external {
        require(!closed);
        next += 1;
        owners[next] = msg.sender;
    }

    function claim(uint256 id) external {
        require(owners[id] == msg.sender && !claimed[id]);
        claimed[id] = true;
