contract Roles {
    mapping(bytes32 => mapping(address => bool)) roles;
    uint256 total;
    bytes32 constant MINTER = keccak256("MINTER");
    event RoleGranted(bytes32 indexed role, address indexed account);
    event RoleRevoked(bytes32 indexed role, address indexed account);

    function grant(bytes32 role, address who) external {
        require(roles[0][msg.sender]);
        roles[role][who] = true;
        emit RoleGranted(role, who);
    }

    function revoke(bytes32 role, address who) external {
        require(roles[0][msg.sender]);
        roles[role][who] = false;
        emit RoleRevoked(role, who);
    }

    function mint() external {
        require(roles[MINTER][msg.sender]);
        total += 1;
    }

    // A loop over the caller's address the engine widens: whether a stranger passes ``mintOr`` is undecided.
    function odd(address a) internal pure returns (bool) {
        uint256 s;
        for (uint256 i; i < uint160(a) % 1000; i++) { s += i; }
        return s == 12345;
    }

    function mintOr() external {
        require(roles[MINTER][msg.sender] || odd(msg.sender));
        last = msg.sender;
    }

    address last;
}

